#' Characterizing Interference Effects
#'
#' 
#' @param data .
#' @param l .
#' @param v .
#' @param ic .
#' @param cb .
#' @param c .
#' @param eb .
#' @param e .
#' @param im .
#' @param iu .
#' @param mm .
#' @param mu .
#' @param alpha .
#' @param wcv .
#' @param wsd .
#' @param wpd .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$text} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$da$t} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$da$m} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$is$t} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$is$c} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$p2p$tt} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$p2p$t} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$p2p$ft} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$p2p$f} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$p2p$i} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$rb$ftd} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$rb$fd1} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$rb$fd2} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$rb$i} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$rb$c} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' @export
CharacterizingInterferenceEffects <- function(
    data,
    l,
    v,
    ic = list(
                list(l=1, c=0),
                list(l=2, c=10),
                list(l=3, c=20),
                list(l=4, c=30),
                list(l=5, c=40)),
    cb,
    c = 5,
    eb,
    e = 10,
    im = "Vitamin C",
    iu = "mg/dL",
    mm = "HbA1c",
    mu = "nmol/L",
    alpha = 0.05,
    wcv = 5,
    wsd = 0.5,
    wpd = 10) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("CharacterizingInterferenceEffects requires jmvcore to be installed (restart may be required)")

    if ( ! missing(l)) l <- jmvcore::resolveQuo(jmvcore::enquo(l))
    if ( ! missing(v)) v <- jmvcore::resolveQuo(jmvcore::enquo(v))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(l), l, NULL),
            `if`( ! missing(v), v, NULL))


    options <- CharacterizingInterferenceEffectsOptions$new(
        l = l,
        v = v,
        ic = ic,
        cb = cb,
        c = c,
        eb = eb,
        e = e,
        im = im,
        iu = iu,
        mm = mm,
        mu = mu,
        alpha = alpha,
        wcv = wcv,
        wsd = wsd,
        wpd = wpd)

    analysis <- CharacterizingInterferenceEffectsClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

